arguments.command:
cd /app; for f in seeds/*; do python3 - $f <<'E'
import sys
b=open(sys.argv[1],'rb').read()
try: b.decode('utf-8'); print(sys.argv[1],'utf8 ok', b[:3]==b'\xef\xbb\xbf', b'\r\n' in b)
except Exception as e: print(sys.argv[1],'not utf8',e)
E
done
python3 - <<'E'
import csv
for f in ['sites','collectors','taxa','specimens']:
    try: r=list(csv.DictReader(open(f'seeds/{f}.csv',encoding='utf-8')))
    except: r=list(csv.DictReader(open(f'seeds/{f}.csv',encoding='cp1252')))
    print(f,len(r))
    if f=='specimens':
        import collections
        print(collections.Counter(x['basis'] for x in r)); print(collections.Counter(len(x['date']) for x in r))
        print([x['elevation_m'] for x in r if not x['elevation_m'].lstrip('-').isdigit()][:10])
E
sqlite3 releases/1.6.0/herbarium.sqlite "select * from schema_migrations" 2>&1 | head -3

